package com.mo.economy_system.common.market;
import com.mo.economy_system.common.network.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class MarketDataQueryServiceTest{
 @Test void filtersSearchesPagesAndPreservesOrder(){UUID me=UUID.randomUUID(),other=UUID.randomUUID();List<MarketOrder> source=List.of(order(MarketOrderType.SALES,me,"Alice"),order(MarketOrderType.DEMAND,other,"Bob"),order(MarketOrderType.SALES,other,"Carol"));var mine=query(source,me,MarketOrderFilter.MINE,"");assertEquals(1,mine.totalMatched());var sales=query(source,me,MarketOrderFilter.SALES,"");assertEquals(2,sales.totalMatched());assertEquals(source.get(0).tradeId(),sales.orders().get(0).tradeId());assertEquals(1,query(source,me,MarketOrderFilter.ALL,"bOb").totalMatched());assertEquals(2,sales.totalSales());assertEquals(1,sales.totalDemand());assertEquals(3,source.size());}
 @Test void handlesSummaryAndOffsetBeyondEnd(){UUID me=UUID.randomUUID();List<MarketOrder> source=List.of(order(MarketOrderType.SALES,me,"A"));var summary=MarketDataQueryService.query(source,me,MarketDataRequestMessage.summary(2));assertEquals(MarketDataResponseKind.SUMMARY,summary.kind());var page=MarketDataQueryService.query(source,me,new MarketDataRequestMessage(3,MarketDataRequestPurpose.PAGE,Integer.MAX_VALUE,100,MarketOrderFilter.ALL,""));assertTrue(page.orders().isEmpty());}
 private static MarketDataResponseMessage query(List<MarketOrder>s,UUID me,MarketOrderFilter f,String q){return MarketDataQueryService.query(s,me,new MarketDataRequestMessage(1,MarketDataRequestPurpose.PAGE,0,100,f,q));}
 private static MarketOrder order(MarketOrderType t,UUID owner,String name){return new MarketOrder(t,UUID.randomUUID(),MarketOrderCodecTest.item(),1,10,name,owner,1,2,false);}
}
